CREATE TEMP TABLE tmp_mml_834_resolved AS
WITH resolved AS (
    SELECT i.*, c.id AS command_id, sp.id AS standard_path_id
    FROM tmp_mml_834_node_add_rows i
    LEFT JOIN public.mml_commands c
      ON c.command_code = i.command_code
     AND c.deprecated_at IS NULL
    LEFT JOIN public.standard_params sp
      ON sp.standard_path = i.standard_path
     AND sp.entry_type = 'parameter'
)
SELECT * FROM resolved;

WITH bound AS (
    SELECT r.*
    FROM tmp_mml_834_resolved r
    JOIN public.mml_command_sub_fields csf
      ON csf.command_id = r.command_id
     AND csf.standard_path_id = r.standard_path_id
     AND csf.deprecated_at IS NULL
)
SELECT
    (SELECT COUNT(*) FROM tmp_mml_834_node_add_rows) AS document_rows,
    (SELECT COUNT(DISTINCT standard_path) FROM tmp_mml_834_node_add_rows) AS document_paths,
    (SELECT COUNT(*) FROM tmp_mml_834_resolved WHERE command_id IS NULL) AS missing_commands,
    (SELECT COUNT(*) FROM tmp_mml_834_resolved WHERE standard_path_id IS NULL) AS missing_standard_paths,
    (SELECT COUNT(*) FROM bound) AS active_bound_rows,
    (SELECT COUNT(*) FROM tmp_mml_834_resolved WHERE command_id IS NOT NULL AND standard_path_id IS NOT NULL) - (SELECT COUNT(*) FROM bound) AS rows_still_missing;

SELECT 'missing_command' AS issue_type, command_code, COUNT(*) AS rows
FROM tmp_mml_834_resolved
WHERE command_id IS NULL
GROUP BY command_code
ORDER BY rows DESC, command_code
LIMIT 50;

SELECT 'missing_standard_path' AS issue_type, standard_path, COUNT(*) AS rows
FROM tmp_mml_834_resolved
WHERE standard_path_id IS NULL
GROUP BY standard_path
ORDER BY rows DESC, standard_path
LIMIT 50;

